steps.script:
# The AI's own charges go first: each unit it would still charge with is
# marked as having charged, until what is left is a real no-charge call.
# (Deterministic stand-in for letting the live AI declare its charges.)
var marked := []
for i in 8:
	var d: Dictionary = AIPlayer.request_suggestion()
	if str(d.get("type", "")) != "DECLARE_CHARGE":
		break
	var uid := str(d.get("actor_unit_id", d.get("unit_id", "")))
	if uid == "" or uid in marked:
		break
	GameState.state.units[uid].flags["charged_this_turn"] = true
	marked.append(uid)
return marked
